"""Bracket matching. Implement is_balanced so the tests pass."""

def is_balanced(s):
    """Return True iff the brackets in s are balanced and correctly nested.
    Brackets are (), [], {}; other characters are ignored. Order matters:
    '([)]' is NOT balanced."""
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or stack.pop() != bracket_map[char]:
                return False
    return not stack
